from .connection import RCIConnection
from .tma_runner import TelnetTMAAppRunner
from taf.internal.robot_typecasts import time_to_seconds
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class rci(object):
    cache = {}
    app_runners_cache = {}
    default_alias = 'default'

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def connect_to(self, ip, command_port, alias=None):
        """Connect to to TM500 external command port.

        :param ip: IP address of the machine that provides external command
            port (probably the one that runs TMAApp.exe).
        :param command_port: The external command port number
        :param alias: (optional) Alias of the connection, which will identify
            it when using other keywords. If no alias is given, a default alias
            is used. There can be only only one connection with a given alias,
            if the same alias is used twice, the first connection will be lost.

        This has to be run before sending any command or trying to disconnect.
        """
        connection = RCIConnection(ip, int(command_port))
        connection.connect()
        self._cache_connection(connection, alias)
        return connection

    def disconnect(self, alias=None):
        """Close connection binded to the given alias.

        :param alias: (optional) Alias of the connection to close. If no alias
        is given, a default alias is used.
        """
        connection = self._lookup_alias(alias)
        connection.disconnect()
        self._decache_connection(alias)

    def send_command(self, command, timeout=None, alias=None):
        """Send a command to TM500 machine or TMAApp, wait for output

        :param command: Command to send (case-insensitive).
        :param alias: (optional) Alias of the connection to close. If no alias
            is given, a default alias is used.
        :param timeout: (optional) amount of time to wait for the confirmation
            message before raising an exception. None by default. Can be given
            in a Robot Framework format (e.g. strings in the following form:
            '5 minutes', '30 s'), where it is implicitly converted into a
            corresponding float value.

            The values given to this parameter are interpreted as follows:
                None - no timeout (wait for confirmation indefinitely)
                any other float - raise an exception, if a confirmation wasn't
                    received in the specified amount of seconds.
        :raises: socket.timeout - if timeout occured.
        :return: Received output. It may not contain all of the 'I: *'
            responses, since those are asynchronous.

        Commands that begin with #$$ are handled by TMAApp. Refer to RCI
        documentation for more information.
        If command is a comment or is empty, the returned value is an empty
        string.
        The command doesn't have to end with a CRLF. The correct line ending is
        ensured before sending.
        """
        timeout = time_to_seconds(timeout)
        connection = self._lookup_alias(alias)
        if not self._empty_or_comment(command):
            connection.send_command(command)
            connection.wait_for_next_confirmation(timeout=timeout)
        return ''.join(connection.get_responses())

    @staticmethod
    def _empty_or_comment(command):
        command = command.strip('\r\n ')
        return ((command.startswith('#') and not command.startswith('#$$'))
                or (not command))

    def send_script(self, filename, timeout=None, alias=None):
        """Send a script from file to TM500 machine.

        :param filename: Path to the file with the script to send.
        :param alias: (optional) Alias of the connection to close. If no alias
            is given, a default alias is used.
        :param timeout: (optional) amount of time to wait for the confirmation
            message after each sent command, before raising an exception. None
            by default. Can be given in a Robot Framework format (e.g. strings
            in the following form: '5 minutes', '30 s'), where it is implicitly
            converted into a corresponding float value.

            The values given to this parameter are interpreted as follows:
                None - no timeout (wait for confirmation indefinitely)
                any other float - raise an exception, if a confirmation wasn't
                    received in the specified amount of seconds.
        :raises: socket.timeout - if timeout occured.
        :return: Received output. It may not contain all of the 'I: *'
            responses, since those are asynchronous.

        The same rules as in 'send_command' keyword apply here.
        """
        with open(filename, 'r') as f:
            script = f.readlines()

        logger.debug("Sending script...")

        output = ''
        for command in script:
            logger.debug(" >> {}".format(repr(command)))

            response = self.send_command(command, timeout=timeout, alias=alias)
            output += response

            logger.debug(" << {}".format(repr(response)))

        return output

    def read_responses(self, alias=None):
        """Return currently available responses / indication messages.

        :param alias: (optional) Alias of the connection to use. If no alias
            is given, a default alias is used.
        :return: A string with all of the received output that hasn't been read
            up to that point. Returns an empty string if no responses could be
            read.
        """
        NON_BLOCKING = 0
        connection = self._lookup_alias(alias)
        last_responses = None
        all_responses = []

        while last_responses != []:
            connection.wait_for_next_response(timeout=NON_BLOCKING)
            last_responses = connection.get_responses()
            all_responses.extend(last_responses)

        return ''.join(all_responses)

    def _lookup_alias(self, alias):
        if alias is None:
            alias = self.default_alias
        return self.cache[alias]

    def _cache_connection(self, connection, alias):
        if alias is None:
            alias = self.default_alias
        self.cache[alias] = connection

    def _decache_connection(self, alias):
        if alias is None:
            alias = self.default_alias
        del self.cache[alias]

    # TODO: Remove this method when deprecated methods are removed
    @staticmethod
    def _warn_deprecated():
        warn_msg = ("Running Test Mobile Application via telnet is deprecated "
                    "and will be removed in the future releases of this "
                    "library.")
        logging.warn(warn_msg)

    def create_telnet_runner(self, host, username, password, alias=None):
        """Create runner instance that runs the TMAApp via telnet.

        :param host: Hostname of the machine that TMAApp should be ran on.
        :param username: Username that will be used to connect to the host via
            telnet.
        :param password: Password that will be used to connect to the host via
            telnet.
        :param alias: - (optional) Alias of the instance, which will identify
            it when using other runner related keywords. If no alias is given,
            a default alias is used. There can be only only one runner instance
            with a given alias, if the same alias is used twice, the first
            runner will be lost. This value will not coincide with the
            connection aliases, i.e.  the same alias can be used for a
            connection and a runner.

        Note, that by default telnet is disable on windows machines. In order
        to use the runner, you must enable it first.
        """
        self._warn_deprecated()
        self._cache_runner(TelnetTMAAppRunner(host, username, password), alias)

    def run_tma_app(self, path=None, user_profile=None, proxy_port=None,
                    auto_proxy=True, auto_disconnect=True, alias=None):
        r"""Run TMAApp via given runner.

        :param path: (optional) Path to TMAApp.exe image. By default,
            "C:\Program Files (x86)\Aeroflex\TM500\V5G - NLZ 2.1.1" is used.
        :param user_profile: (optional) User profile that will be loaded by
            TMAApp. By default "Default User" is used.
        :param proxy_port: (optional) Integer value that specifies a port
            number that the TMAApp should run external command interface on. By
            default 5003 is used.
        :param auto_proxy: (optional) If True, the '/c' flag will be added when
            running TMAApp. This will make it create the external proxy when
            running. True by default.
        :param auto_disconnect: - (optional) If True, the '/a' flag will be
            added when running TMAApp. This will make it automatically
            disconnect from TM500 machine if the external command interface
            connection is closed. True by default.
        :param alias: (optional) Alias of the runner to use. If no alias is
            given, a default alias is used.
        """
        self._warn_deprecated()
        runner = self._lookup_runner_alias(alias)
        runner.run(path=path, user_profile=user_profile,
                   proxy_port=proxy_port, auto_proxy=auto_proxy,
                   auto_disconnect=auto_disconnect)

    def kill_tma_app(self, imagename=None, alias=None):
        """Tell the host to kill a process with the given imagename.

        :param imagename: (optional) The process name that will be killed. By
            default "TMA.exe" is used. This is the same name that is visible in
            Windows Task Manager.
        :param alias: (optional) Alias of the runner to use. If no alias is
            given, a default alias is used.

        This will raise ValueError if no process with given imagename was found
        on the host, or RuntimeError if it failed to kill the specified
        process.
        """
        self._warn_deprecated()
        self._lookup_runner_alias(alias).kill(imagename=imagename)

    def tma_app_is_running(self, imagename=None, alias=None):
        """Tell if the process with given imagename is running on the host.

        :param imagename: (optional) The process name that will be checked. By
            default "TMA.exe" is used. This is the same name that is visible in
            Windows Task Manager.
        :param alias: (optional) Alias of the runner to use. If no alias is
            given, a default alias is used.
        :return: True if the process is running, False otherwise.
        """
        self._warn_deprecated()
        return self._lookup_runner_alias(alias).is_running(imagename=imagename)

    def _lookup_runner_alias(self, alias):
        if alias is None:
            alias = self.default_alias
        return self.app_runners_cache[alias]

    def _cache_runner(self, runner, alias):
        if alias is None:
            alias = self.default_alias
        self.app_runners_cache[alias] = runner

    def _decache_runner(self, alias):
        if alias is None:
            alias = self.default_alias
        del self.app_runners_cache[alias]
